llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "In humans, cis-lycopene, a highly lipophilic C40 isoprenoid, showed 24.5% ± 6% bioavailability after oral consumption, demonstrating that long-chain isoprenoid lipids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Phytoene, an acyclic long-chain isoprenoid, was estimated to have 58.5 ± 18.9% bioavailability in human subjects by compartmental modeling, supporting meaningful oral absorption for highly lipophilic isoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Hyperforin, a prenylated lipophilic natural product, showed high oral bioavailability in volunteers after extract administration, supporting absorption of large lipophilic prenylated molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Finerenone had an absolute oral bioavailability of 43.5% in humans, providing direct evidence that F>=20% is achievable despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The active metabolite of nabumetone had 38% systemic availability in healthy subjects, another example of a lipophilic compound exceeding the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The experimental evidence, especially from structurally relevant lipophilic isoprenoids (lycopene, phytoene) and prenylated natural products (hyperforin), consistently shows oral bioavailability at or above 20%. Although the physicochemical prior predicts low absorption due to extreme lipophilicity and high molecular weight, the transferable experimental measurements override this prior. Therefore, the query is predicted high (F>=20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ10) itself.",
    "Carotenoid bioavailability values are based on plasma appearance/compartmental modeling rather than strict IV-referenced absolute bioavailability.",
    "Formulation, food effects, and dose-dependent absorption for the query are not captured by the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

